<?php

namespace App\Support;

use App\Models\Widget;

/**
 * Per-widget engagement settings stored in widgets.engagement (JSON):
 * the AI notice shown before the first message, pages where the widget stays hidden,
 * and action cards shown under matching answers.
 */
class Engagement
{
    public const DEFAULTS = [
        'ai_notice' => [
            'enabled'      => false,
            'title'        => 'You are chatting with an AI assistant',
            'text'         => 'Answers are generated by AI and may not always be accurate. What you type is stored to answer you and improve our service.',
            'privacy_url'  => '',
            'decline_text' => 'No problem. You can still contact us another way, or accept to start chatting.',
        ],
        'hidden_paths' => [],   // e.g. ["/checkout*", "/account/*"]
        'cards'        => [],   // [{title, text, button, url, keywords}]
        // Team availability for "Talk to a human" (the AI answers 24/7).
        'hours'        => ['enabled' => false, 'timezone' => 'UTC', 'days' => ['mon' => ['09:00', '17:00'], 'tue' => ['09:00', '17:00'], 'wed' => ['09:00', '17:00'], 'thu' => ['09:00', '17:00'], 'fri' => ['09:00', '17:00'], 'sat' => null, 'sun' => null],
            'away_text' => 'Our team is offline right now. I can still help, or leave a message and we will reply when we are back.'],
    ];

    public static function settings(Widget $widget): array
    {
        $s = is_array($widget->engagement) ? $widget->engagement : (json_decode((string) $widget->engagement, true) ?: []);

        return [
            'ai_notice'    => array_merge(self::DEFAULTS['ai_notice'], $s['ai_notice'] ?? []),
            'hidden_paths' => array_values(array_filter((array) ($s['hidden_paths'] ?? []), 'is_string')),
            'cards'        => array_values(array_filter((array) ($s['cards'] ?? []), 'is_array')),
            'hours'        => array_merge(self::DEFAULTS['hours'], (array) ($s['hours'] ?? [])),
        ];
    }

    /** Is the team available now? Always true when business hours are off. */
    public static function teamOnline(Widget $widget, ?\DateTimeInterface $at = null): bool
    {
        $h = self::settings($widget)['hours'];
        if (empty($h['enabled'])) return true;
        try {
            $now = \Carbon\CarbonImmutable::instance($at ?? now())->setTimezone($h['timezone'] ?: 'UTC');
        } catch (\Throwable) {
            $now = \Carbon\CarbonImmutable::now('UTC');
        }
        $day = $h['days'][strtolower($now->format('D'))] ?? null;
        if (! is_array($day) || count($day) < 2) return false;
        $t = $now->format('H:i');

        return $t >= $day[0] && $t < $day[1];
    }

    /** Glob match against the page path, e.g. "/checkout*" or "/blog/*". */
    public static function hiddenOn(Widget $widget, string $pageUrl): bool
    {
        $path = parse_url($pageUrl, PHP_URL_PATH) ?: '/';
        foreach (self::settings($widget)['hidden_paths'] as $glob) {
            $glob = '/' . ltrim(trim($glob), '/');
            if ($glob !== '/' && fnmatch($glob, $path)) return true;
            if ($glob === '/' && $path === '/') return true;
        }

        return false;
    }

    /** Up to three cards whose keywords appear in the visitor question or the answer. */
    public static function cardsFor(Widget $widget, string $text): array
    {
        $t = ' ' . \App\Models\KnowledgeGap::normalize($text) . ' ';
        $out = [];
        foreach (self::settings($widget)['cards'] as $c) {
            foreach (array_filter(array_map(fn ($k) => \App\Models\KnowledgeGap::normalize($k), explode(',', (string) ($c['keywords'] ?? '')))) as $k) {
                if (str_contains($t, " $k ")) {
                    $out[] = ['title' => $c['title'] ?? '', 'text' => $c['text'] ?? '', 'button' => $c['button'] ?? 'Open', 'url' => $c['url'] ?? ''];
                    break;
                }
            }
            if (count($out) === 3) break;
        }

        return $out;
    }

    /** Glob-style page targeting for proactive rules (no user-supplied regex). */
    public static function pageMatches(?string $pattern, string $pageUrl): bool
    {
        $pattern = trim((string) $pattern);
        if ($pattern === '' || $pageUrl === '') return true;
        $path = parse_url($pageUrl, PHP_URL_PATH) ?: '/';

        return str_contains($pattern, '*') ? fnmatch('/' . ltrim($pattern, '/'), $path) : str_contains(mb_strtolower($pageUrl), mb_strtolower($pattern));
    }
}
